#!/usr/bin/env bash
# setup-it-atlas.sh — one-shot installer for the IT Atlas Obsidian vault
# macOS and Linux. Safe to re-run: never deletes anything, backs up instead.
#
# Usage:  bash setup-it-atlas.sh [options]
#   --dir PATH     where to create the vault (default: ~/Documents/IT-Atlas)
#   --force        if the folder exists, move it to a timestamped backup and reinstall
#   --yes          answer yes to prompts (install Obsidian / Claude Code without asking)
#   --no-obsidian  don't install Obsidian
#   --no-plugins   don't download the Dataview plugin
#   --no-git       don't initialise a git repo
#   --no-claude    don't check for / offer to install Claude Code
#   --no-open      don't register or open the vault in Obsidian
set -euo pipefail

VAULT_DIR="$HOME/Documents/IT-Atlas"
FORCE=0; YES=0; DO_OBS=1; DO_PLUG=1; DO_GIT=1; DO_CLAUDE=1; DO_OPEN=1
while [ $# -gt 0 ]; do
  case "$1" in
    --dir) VAULT_DIR="${2:?--dir needs a path}"; shift 2 ;;
    --force) FORCE=1; shift ;;
    --yes|-y) YES=1; shift ;;
    --no-obsidian) DO_OBS=0; shift ;;
    --no-plugins) DO_PLUG=0; shift ;;
    --no-git) DO_GIT=0; shift ;;
    --no-claude) DO_CLAUDE=0; shift ;;
    --no-open) DO_OPEN=0; shift ;;
    -h|--help) sed -n '2,15p' "$0"; exit 0 ;;
    *) echo "Unknown option: $1"; exit 2 ;;
  esac
done

if [ -t 1 ]; then B=$'\e[1m'; G=$'\e[32m'; Y=$'\e[33m'; R=$'\e[31m'; N=$'\e[0m'; else B=; G=; Y=; R=; N=; fi
step() { printf "\n${B}==> %s${N}\n" "$*"; }
ok()   { printf "   ${G}✓${N} %s\n" "$*"; }
warn() { printf "   ${Y}!${N} %s\n" "$*"; }
die()  { printf "   ${R}✗ %s${N}\n" "$*"; exit 1; }
have() { command -v "$1" >/dev/null 2>&1; }
ask()  { [ "$YES" = 1 ] && return 0; [ -t 0 ] || return 1; read -r -p "   $1 [y/N] " a; [[ "$a" =~ ^[Yy] ]]; }

OS="$(uname -s)"
case "$OS" in Darwin) PLAT=mac ;; Linux) PLAT=linux ;; *) die "Unsupported OS: $OS (macOS or Linux only)";; esac
case "$VAULT_DIR" in /*) ;; *) VAULT_DIR="$PWD/$VAULT_DIR" ;; esac
TS="$(date +%Y%m%d-%H%M%S)"
SELF="${BASH_SOURCE[0]}"

# ---------------------------------------------------------------- 1. extract
step "Creating vault at $VAULT_DIR"
for t in tar; do have "$t" || die "'$t' is required"; done
if [ -e "$VAULT_DIR" ]; then
  if [ "$FORCE" = 1 ]; then
    mv "$VAULT_DIR" "$VAULT_DIR.backup-$TS"
    warn "Existing folder moved to $VAULT_DIR.backup-$TS"
  else
    die "$VAULT_DIR already exists. Re-run with --force to back it up and reinstall, or --dir to pick another location."
  fi
fi
if printf 'QQ==' | base64 --decode >/dev/null 2>&1; then B64D="base64 --decode"; else B64D="base64 -D"; fi
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
sed -n '/^__VAULT_ARCHIVE_BELOW__$/,$p' "$SELF" | tail -n +2 | $B64D | tar -xz -C "$TMP" \
  || die "Couldn't unpack the embedded vault (is the script complete?)"
mkdir -p "$(dirname "$VAULT_DIR")"
mv "$TMP/IT-Atlas" "$VAULT_DIR"
ok "$(find "$VAULT_DIR" -name '*.md' -not -path '*/.claude/*' -not -path '*/.obsidian/*' | wc -l | tr -d ' ') notes (fixes, tools, concepts, playbooks, tracks, reference) in place"

# ---------------------------------------------------------------- 2. Obsidian
OBS_FOUND=0
obs_installed() {
  if [ "$PLAT" = mac ]; then [ -d "/Applications/Obsidian.app" ] || [ -d "$HOME/Applications/Obsidian.app" ]
  else have obsidian || (have flatpak && flatpak info md.obsidian.Obsidian >/dev/null 2>&1) || ls "$HOME"/Applications/Obsidian*.AppImage >/dev/null 2>&1; fi
}
if [ "$DO_OBS" = 1 ]; then
  step "Checking Obsidian"
  if obs_installed; then ok "Obsidian already installed"; OBS_FOUND=1
  elif [ "$PLAT" = mac ] && have brew; then
    if ask "Obsidian not found. Install it with Homebrew?"; then
      brew install --cask obsidian && OBS_FOUND=1 && ok "Obsidian installed"
    else warn "Skipped. Download from https://obsidian.md/download"; fi
  elif [ "$PLAT" = linux ] && have flatpak; then
    if ask "Obsidian not found. Install it with Flatpak (Flathub)?"; then
      flatpak install -y --user flathub md.obsidian.Obsidian && OBS_FOUND=1 && ok "Obsidian installed"
    else warn "Skipped. Download from https://obsidian.md/download"; fi
  else
    warn "Obsidian not found and no Homebrew/Flatpak to install it. Download from https://obsidian.md/download"
  fi
fi

# ---------------------------------------------------------------- 3. plugins
if [ "$DO_PLUG" = 1 ]; then
  step "Plugins"
  ok "Dataview and the IT Atlas 3D brain plugin are already inside the vault. Obsidian will ask you to trust the vault the first time it opens."
fi

# ---------------------------------------------------------------- 4. git
if [ "$DO_GIT" = 1 ]; then
  step "Setting up git"
  if have git; then
    git -C "$VAULT_DIR" init -q
    git -C "$VAULT_DIR" add -A
    if git -C "$VAULT_DIR" config user.name >/dev/null && git -C "$VAULT_DIR" config user.email >/dev/null; then
      git -C "$VAULT_DIR" commit -qm "atlas: initial import" && ok "Repo initialised with a first commit"
    else
      warn "Repo initialised, but git has no user.name/user.email set, so nothing was committed."
      warn "Set them with: git config --global user.name \"Rehan Khan\"; git config --global user.email you@example.com"
    fi
  else warn "git not found. Skipping (Claude can still edit the vault, you just lose undo history)."; fi
fi

# ---------------------------------------------------------------- 5. Claude Code
if [ "$DO_CLAUDE" = 1 ]; then
  step "Checking Claude Code"
  if have claude; then ok "Claude Code found ($(claude --version 2>/dev/null | head -1))"
  elif ask "Claude Code not found. Install it with the official installer (curl https://claude.ai/install.sh)?"; then
    curl -fsSL https://claude.ai/install.sh | bash && ok "Claude Code installed. Open a new terminal so 'claude' is on your PATH."
  else warn "Skipped. Install later from https://docs.claude.com/en/docs/claude-code"; fi
fi

# ---------------------------------------------------------------- 6. lint
step "Checking links"
if have python3; then
  if (cd "$VAULT_DIR" && python3 _system/vault_lint.py >/tmp/vault-lint-$TS.txt 2>&1); then
    ok "No broken links or missing fields ($(sed -n 's/^Notes scanned: \([0-9]*\).*/\1/p' /tmp/vault-lint-$TS.txt) notes scanned)"
  else warn "Lint reported issues:"; sed 's/^/     /' /tmp/vault-lint-$TS.txt; fi
  rm -f /tmp/vault-lint-$TS.txt
else warn "python3 not found. Skipping the link check (Claude Code's /lint needs python3)."; fi

# ---------------------------------------------------------------- 7. register + open
if [ "$DO_OPEN" = 1 ] && { [ "$OBS_FOUND" = 1 ] || obs_installed; }; then
  step "Opening in Obsidian"
  if [ "$PLAT" = mac ]; then CFG="$HOME/Library/Application Support/obsidian/obsidian.json"
  elif [ -d "$HOME/.var/app/md.obsidian.Obsidian" ]; then CFG="$HOME/.var/app/md.obsidian.Obsidian/config/obsidian/obsidian.json"
  else CFG="$HOME/.config/obsidian/obsidian.json"; fi
  RUNNING=0; pgrep -xi obsidian >/dev/null 2>&1 && RUNNING=1
  if [ "$RUNNING" = 0 ] && have python3; then
    mkdir -p "$(dirname "$CFG")"
    [ -f "$CFG" ] && cp "$CFG" "$CFG.backup-$TS"
    python3 - "$CFG" "$VAULT_DIR" <<'PY'
import json, os, sys, time, secrets
cfg, path = sys.argv[1], sys.argv[2]
data = {}
if os.path.exists(cfg):
    try: data = json.load(open(cfg))
    except Exception: data = {}
vaults = data.setdefault("vaults", {})
for v in vaults.values(): v.pop("open", None)
vid = next((k for k, v in vaults.items() if v.get("path") == path), secrets.token_hex(8))
vaults[vid] = {"path": path, "ts": int(time.time() * 1000), "open": True}
json.dump(data, open(cfg, "w"))
PY
    ok "Vault registered with Obsidian"
    if [ "$PLAT" = mac ]; then open -a Obsidian
    elif have obsidian; then (obsidian >/dev/null 2>&1 &)
    elif have flatpak; then (flatpak run md.obsidian.Obsidian >/dev/null 2>&1 &); fi
    ok "Launched Obsidian"
  else
    [ "$RUNNING" = 1 ] && warn "Obsidian is running, so its vault list wasn't touched."
    warn "In Obsidian: Open another vault → Open folder as vault → $VAULT_DIR"
  fi
fi

# ---------------------------------------------------------------- done
step "Done"
cat <<EOF
   Vault:   $VAULT_DIR
   Start:   open "Start here" or "00 Home/Home", then the graph view.
   Claude:  cd "$VAULT_DIR" && claude
            then try /add-tool, /add-playbook, /verify, /gaps, /lint
EOF
exit 0
